using System.Buffers.Binary;
using System.Text.Json;
namespace OcctSharp.Tests.Shared;
internal static class BatchBKWireChecks {
 internal static void Check(string path){using var json=JsonDocument.Parse(File.ReadAllBytes(path));var root=json.RootElement;var accessors=root.GetProperty("accessors");var views=root.GetProperty("bufferViews");var buffers=root.GetProperty("buffers");
  double[] Values(int index,int dimensions){var accessor=accessors[index];int count=accessor.GetProperty("count").GetInt32();BatchBKConfiguredMeshWorkflow.Require(count>0&&count<=1048576&&!accessor.TryGetProperty("sparse",out _),"wire accessor budget/profile");int component=accessor.GetProperty("componentType").GetInt32();int size=component==5126||component==5125?4:component==5123?2:component==5121?1:throw new InvalidDataException("Unexpected wire component.");var view=views[accessor.GetProperty("bufferView").GetInt32()];string uri=buffers[view.GetProperty("buffer").GetInt32()].GetProperty("uri").GetString()!;BatchBKConfiguredMeshWorkflow.Require(Path.GetFileName(uri)==uri,"wire buffer filename");byte[] bytes=File.ReadAllBytes(Path.Combine(Path.GetDirectoryName(path)!,uri));int offset=(view.TryGetProperty("byteOffset",out var start)?start.GetInt32():0)+(accessor.TryGetProperty("byteOffset",out var extra)?extra.GetInt32():0),stride=view.TryGetProperty("byteStride",out var step)?step.GetInt32():dimensions*size;var output=new double[checked(count*dimensions)];for(int n=0;n<count;++n)for(int d=0;d<dimensions;++d){int at=checked(offset+n*stride+d*size);output[n*dimensions+d]=component switch{5126=>BitConverter.Int32BitsToSingle(BinaryPrimitives.ReadInt32LittleEndian(bytes.AsSpan(at,4))),5125=>BinaryPrimitives.ReadUInt32LittleEndian(bytes.AsSpan(at,4)),5123=>BinaryPrimitives.ReadUInt16LittleEndian(bytes.AsSpan(at,2)),_=>bytes[at]};}return output;}
  foreach(var mesh in root.GetProperty("meshes").EnumerateArray())foreach(var primitive in mesh.GetProperty("primitives").EnumerateArray()){var attributes=primitive.GetProperty("attributes");double[] points=Values(attributes.GetProperty("POSITION").GetInt32(),3),normals=Values(attributes.GetProperty("NORMAL").GetInt32(),3),indices=Values(primitive.GetProperty("indices").GetInt32(),1);BatchBKConfiguredMeshWorkflow.Require(points.Length==normals.Length,"wire normal domain");for(int n=0;n<points.Length;n+=3){BatchBKConfiguredMeshWorkflow.Require(points[n]>=-1e-6&&points[n]<=.002001&&points[n+1]>=-1e-6&&points[n+1]<=.004001&&points[n+2]>=-.003001&&points[n+2]<=1e-6,"native wire points are meters with exact Z-to-Y conversion");double length=Math.Sqrt(normals[n]*normals[n]+normals[n+1]*normals[n+1]+normals[n+2]*normals[n+2]);BatchBKConfiguredMeshWorkflow.Require(Math.Abs(length-1)<1e-5,"wire unit normal");}for(int t=0;t<indices.Length;t+=3){int a=checked((int)indices[t]*3),b=checked((int)indices[t+1]*3),c=checked((int)indices[t+2]*3);double ux=points[b]-points[a],uy=points[b+1]-points[a+1],uz=points[b+2]-points[a+2],vx=points[c]-points[a],vy=points[c+1]-points[a+1],vz=points[c+2]-points[a+2],nx=uy*vz-uz*vy,ny=uz*vx-ux*vz,nz=ux*vy-uy*vx,length=Math.Sqrt(nx*nx+ny*ny+nz*nz);BatchBKConfiguredMeshWorkflow.Require(length>0&&(nx*normals[a]+ny*normals[a+1]+nz*normals[a+2])/length>.9999,"converted normals agree with native wire triangle orientation");}}
 }
